{"name":"auth","qualified_name":"Users-appointy-Documents-New-project-6.internal.taskpilot.server.auth","label":"Method","file_path":"/Users/appointy/Documents/New project 6/internal/taskpilot/server.go","start_line":128,"end_line":156,"source":"func (s *Server) auth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if p, ok := s.authPrincipal(r); ok {
			ctx := context.WithValue(r.Context(), actorKey{}, p.ActorID)
			ctx = context.WithValue(ctx, principalKey{}, p)
			next.ServeHTTP(w, r.WithContext(ctx))
			return
		}
		actorID := r.Header.Get("X-Actor-ID")
		if actorID != "" {
			ok, err := s.store.VerifyActorSecret(r.Context(), actorID, r.Header.Get("X-Actor-Secret"))
			if err != nil {
				writeErr(w, http.StatusInternalServerError, err)
				return
			}
			if !ok {
				writeErr(w, http.StatusUnauthorized, userErr("unauthorized", "invalid actor credentials"))
				return
			}
			s.store.TouchActor(r.Context(), actorID)
			p := Principal{ID: actorID, Kind: "legacy_actor", ActorID: actorID}
			ctx := context.WithValue(r.Context(), actorKey{}, actorID)
			ctx = context.WithValue(ctx, principalKey{}, p)
			next.ServeHTTP(w, r.WithContext(ctx))
			return
		}
		writeErr(w, http.StatusUnauthorized, userErr("unauthorized", "sign in or provide valid actor credentials"))
	})
}
