{"name":"authPrincipal","qualified_name":"Users-appointy-Documents-New-project-6.internal.taskpilot.server.authPrincipal","label":"Method","file_path":"/Users/appointy/Documents/New project 6/internal/taskpilot/server.go","start_line":171,"end_line":188,"source":"func (s *Server) authPrincipal(r *http.Request) (Principal, bool) {
	if cookie, err := r.Cookie("taskpilot_session"); err == nil {
		p, err := s.store.VerifySession(r.Context(), cookie.Value)
		if err != nil {
			return Principal{}, false
		}
		if p.Kind == "user" && p.UserID != "" {
			actor, err := s.store.EnsureDefaultActorForUser(r.Context(), User{ID: p.UserID, Email: p.Email, Name: p.Name})
			if err != nil {
				return Principal{}, false
			}
			p.ActorID = actor.ID
			s.store.TouchActor(r.Context(), actor.ID)
		}
		return p, true
	}
	return Principal{}, false
}
