		return Task{}, err
	}
	if err := s.renewTaskLocks(ctx, actorID, t.ID, now); err != nil {
		return Task{}, err
	}
	return t, s.addEvent(ctx, t.ID, actorID, "task.heartbeat", map[string]any{"claim_expires_at": exp})
}
