+
+func parentWouldCreateCycle(ctx context.Context, s *Store, childID, parentID string) bool {
+	for parentID != "" {
+		if parentID == childID {
+			return true
+		}
+		parent, err := s.GetTask(ctx, parentID)
+		if err != nil {
+			return false
+		}
+		parentID = parent.ParentTaskID
+	}
+	return false
+}
